style.css:
@-moz-document domain("youtube.com") {
/* Fondo general */
  body, ytd-app {
    background-color: #ffe4f2 !important;
    color: #d4006f !important;
  }

  /* Fondo de la barra de búsqueda */
  #search-form {
    background-color: #ffd6ec !important;
  }

  /* Cambiar el color del texto del buscador */
  #search-input, input#search {
    color: #d4006f !important;
    background-color: #fff0f6 !important;
  }

  /* Color de títulos y textos */
  h1, h2, h3, ytd-video-renderer, ytd-rich-item-renderer, #video-title, .style-scope.ytd-video-renderer {
    color: #d4006f !important;
  }

  /* Fondo de los vídeos en el inicio */
  ytd-rich-grid-renderer, ytd-rich-grid-row, ytd-rich-item-renderer {
    background-color: #ffeef7 !important;
  }

  /* Botones */
  tp-yt-paper-button, ytd-button-renderer {
    background-color: #ffb6d9 !important;
    color: #d4006f !important;
  }

  /* Borde y efectos hover */
  *:hover {
    border-color: #ff80bf !important;
    color: #e60073 !important;
  }
}
